/* ---------- Pembaca Excel mingguan ---------- */
const STATUSES = ['DONE', 'IN PROGRESS', 'TODO', 'BACKLOG'];
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

function formatDate(value) {
  if (value == null || value === '' || value === '-') return '-';
  let date = null;
  if (value instanceof Date) date = value;
  else if (typeof value === 'number' && value > 20000 && value < 70000) date = new Date(Math.round((value - 25569) * 86400000));
  if (date && !Number.isNaN(date.getTime())) return `${String(date.getUTCDate()).padStart(2,'0')} ${MONTHS[date.getUTCMonth()] || 'Jan'} ${date.getUTCFullYear()}`;
  return String(value).trim() || '-';
}
function parseDate(value) {
  if (!value || value === '-') return null;
  const match = value.match(/^(\d{1,2})[ /-]([A-Za-z]+|\d{1,2})[ /-](\d{4})$/);
  if (match) {
    const part = match[2] || '';
    const month = /^\d+$/.test(part) ? Number(part) - 1 : MONTHS.findIndex(m => m.toLowerCase() === part.slice(0,3).toLowerCase());
    if (month >= 0 && month < 12) { const d = new Date(Number(match[3]), month, Number(match[1])); return Number.isNaN(d.getTime()) ? null : d; }
  }
  const d = new Date(value); return Number.isNaN(d.getTime()) ? null : d;
}
function overdueDays(t) {
  if (t.Status === 'DONE') return 0;
  const date = parseDate(t['Due Date']);
  if (!date) return 0;
  const now = new Date(); now.setHours(0,0,0,0);
  return Math.max(0, Math.floor((now.getTime() - date.getTime()) / 86400000));
}
const clean = value => String(value == null ? '' : value).trim() || '-';
function normalizeRow(row) {
  const t = { Project:'-', 'Task Name':'-', Status:'TODO', Type:'System', PIC:'-', From:'-', 'Due Date':'-', 'Actual Date':'-' };
  Object.entries(row).forEach(([key, value]) => {
    const k = key.toLowerCase().trim().replace(/[_-]/g, ' ');
    if (/^(project|proyek|stream|nama project|nama proyek)/.test(k)) t.Project = clean(value);
    else if (/^(task type|task kategori|type|jenis|kategori|tipe)/.test(k)) t.Type = clean(value);
    else if (/^(task name|task|pekerjaan|nama task|aktivitas|item)/.test(k)) t['Task Name'] = clean(value);
    else if (/^(status|kondisi|state)/.test(k) && !k.includes('project')) t.Status = clean(value).toUpperCase();
    else if (/^(pic|nama pic|resource|orang|assign|owner)/.test(k)) t.PIC = clean(value);
    else if (/^(from|mulai|start|tgl mulai)/.test(k)) t.From = formatDate(value);
    else if (/^(actual|realisasi|tgl selesai)/.test(k)) t['Actual Date'] = formatDate(value);
    else if (/^(due|tenggat|target date|deadline|tgl target)/.test(k)) t['Due Date'] = formatDate(value);
  });
  const s = t.Status.toUpperCase();
  if (/DONE|SELESAI|FINISH|COMPLETE/.test(s)) t.Status = 'DONE';
  else if (/PROG|JALAN|PROSES/.test(s)) t.Status = 'IN PROGRESS';
  else if (/BACKLOG|PENDING|HOLD/.test(s)) t.Status = 'BACKLOG';
  else if (/TODO|TO DO|BELUM/.test(s)) t.Status = 'TODO';
  return t;
}
async function readTasks(file) {
  const content = file.name.toLowerCase().endsWith('.csv') ? await file.text() : await file.arrayBuffer();
  const book = XLSX.read(content, { type: typeof content === 'string' ? 'string' : 'array', cellDates: true });
  const name = book.SheetNames[0];
  const sheet = name ? book.Sheets[name] : undefined;
  if (!sheet) throw new Error('Sheet tidak ditemukan.');
  const rows = XLSX.utils.sheet_to_json(sheet, { defval: '-' });
  const result = rows.map(normalizeRow).filter(t => t.Project !== '-' || t['Task Name'] !== '-');
  if (!result.length) throw new Error('Tidak ada baris task yang terbaca. Periksa judul kolom file Anda.');
  return result;
}
function exportFile(tasks, type) {
  const headers = ['Project','Task Name','Status','Type','PIC','From','Due Date','Overdue Date'];
  const rows = tasks.map(t => ({ Project: t.Project, 'Task Name': t['Task Name'], Status: t.Status, Type: t.Type, PIC: t.PIC, From: t.From, 'Due Date': t['Due Date'], 'Overdue Date': overdueDays(t) ? `${overdueDays(t)} hari` : '-' }));
  const sheet = XLSX.utils.json_to_sheet(rows, { header: headers });
  const workbook = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(workbook, sheet, 'Weekly Tasks');
  XLSX.writeFile(workbook, `PMO_Weekly_Tasks_${new Date().toISOString().slice(0,10)}.${type}`, { bookType: type });
}

/* ---------- Pembaca pivot Odoo ---------- */
function parsePivotRows(matrix, filename) {
  const header = matrix.findIndex(row => row.some(cell => String(cell == null ? '' : cell).trim().toLowerCase() === 'count'));
  const countColumn = header >= 0 ? matrix[header].findIndex(cell => String(cell == null ? '' : cell).trim().toLowerCase() === 'count') : -1;
  if (header < 0 || countColumn < 1) throw new Error('Kolom Count dan nama proyek tidak ditemukan pada pivot.');
  const counts = new Map();
  let declaredTotal;
  for (const row of matrix.slice(header + 1)) {
    const project = String(row[0] == null ? '' : row[0]).trim();
    if (!project) continue;
    const raw = row[countColumn];
    const count = typeof raw === 'number' ? raw : Number(String(raw == null ? '' : raw).trim());
    if (raw == null || raw === '' || !Number.isSafeInteger(count) || count < 0) throw new Error(`Count untuk ${project} harus berupa bilangan bulat nonnegatif.`);
    if (/^(grand total|total)$/i.test(project)) { declaredTotal = count; continue; }
    counts.set(project, (counts.get(project) || 0) + count);
  }
  const rows = [...counts].map(([project, count]) => ({ project, count })).sort((a, b) => a.project.localeCompare(b.project, 'en'));
  if (!rows.length) throw new Error('Pivot tidak memiliki baris proyek.');
  const total = rows.reduce((sum, row) => sum + row.count, 0);
  if (declaredTotal !== undefined && declaredTotal !== total) throw new Error('Total pivot tidak sama dengan jumlah Count proyek.');
  return { filename, rows, total };
}
async function readPivot(file) {
  const book = XLSX.read(await file.arrayBuffer(), { type: 'array' });
  for (const name of book.SheetNames) {
    const sheet = book.Sheets[name];
    if (!sheet) continue;
    const matrix = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null });
    if (matrix.some(row => row.some(cell => String(cell == null ? '' : cell).trim().toLowerCase() === 'count'))) return parsePivotRows(matrix, file.name);
  }
  throw new Error('File bukan pivot Tasks Analysis dengan kolom Count.');
}

/* ---------- Screenshot laporan ---------- */
const SHOT_TITLES = ['Support Functional Summary by Date', 'Support Functional Summary'];
function validScreenshot(value) {
  return typeof value === 'string' && /^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(value) && value.length <= 7000000;
}
function normalizeScreenshots(value) {
  const values = Array.isArray(value) ? value : [];
  return [validScreenshot(values[0]) ? values[0] : null, validScreenshot(values[1]) ? values[1] : null];
}
function readScreenshot(file) {
  if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type)) return Promise.reject(new Error('Gunakan gambar PNG, JPG, atau WebP.'));
  if (file.size > 5 * 1024 * 1024) return Promise.reject(new Error('Ukuran screenshot maksimal 5 MB.'));
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error('Screenshot tidak dapat dibaca.'));
    reader.onload = () => validScreenshot(reader.result) ? resolve(reader.result) : reject(new Error('Screenshot tidak valid.'));
    reader.readAsDataURL(file);
  });
}

/* ---------- Diagram laporan (SVG) ---------- */
const openReportTasks = tasks => tasks.filter(t => t.Status !== 'DONE');
const reportProjects = tasks => [...new Set(tasks.map(t => t.Project))];
const uniqueKeep = values => [...new Set(values)];
const pivotProjectRank = project => {
  const rank = ['img', 'mnc3tv', 'mncholding', 'none'].indexOf(project.toLowerCase().replace(/[\s_-]/g, ''));
  return rank < 0 ? 4 : rank;
};
const chunks = (values, size) => Array.from({ length: Math.ceil(values.length / size) }, (_, i) => values.slice(i * size, (i + 1) * size));
const dayKey = value => {
  const d = parseDate(value);
  return d ? `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}` : 'Tanpa tanggal';
};

/* Counts use From (start date), not a fabricated ticket-created timestamp. Every row is represented. */
function buildReportCharts(tasks, single = false, pivot) {
  const open = openReportTasks(tasks);
  const rawDays = uniqueKeep(open.map(t => dayKey(t.From)));
  const weekly = single && rawDays.length > 14;
  const bucket = value => {
    const k = dayKey(value);
    if (!weekly || k === 'Tanpa tanggal') return k;
    const d = new Date(k); d.setDate(d.getDate() - ((d.getDay() + 6) % 7));
    return `Minggu ${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  };
  const big = single ? 1e9 : 0;
  const projects = uniqueKeep(open.map(t => t.Project));
  const statuses = uniqueKeep(open.map(t => t.Status));
  const days = uniqueKeep(open.map(t => bucket(t.From))).sort((a, b) => a === 'Tanpa tanggal' ? 1 : b === 'Tanpa tanggal' ? -1 : a.localeCompare(b));
  const dated = (series, field) => days.map(label => ({ label, values: series.map(name => open.filter(t => bucket(t.From) === label && t[field] === name).length) }));
  const byDate = chunks(projects, big || 8).flatMap(series => chunks(dated(series, 'Project'), big || 12).map(rows => ({ title: 'Task by Start Date & Project', subtitle: 'Tanggal mulai (From) · task belum DONE', kind: 'stack', series, rows, total: rows.reduce((n, r) => n + r.values.reduce((a, b) => a + b, 0), 0) })));
  const byStatus = chunks(dated(statuses, 'Status'), big || 12).map(rows => ({ title: 'Task by Start Date & Status', subtitle: 'Tanggal mulai (From) · status task saat ini, bukan riwayat perubahan', kind: 'line', series: statuses, rows, total: rows.reduce((n, r) => n + r.values.reduce((a, b) => a + b, 0), 0) }));
  const byProject = chunks(projects, big || 10).map(series => ({ title: 'Task Summary by Project', subtitle: 'Jumlah task belum DONE per proyek', kind: 'column', series: ['Count'], rows: series.map(label => ({ label, values: [open.filter(t => t.Project === label).length] })), total: open.filter(t => series.includes(t.Project)).length }));
  const empty = (title, kind) => ({ title, subtitle: 'Tidak ada task belum DONE', kind, series: [], rows: [], total: 0 });
  const pivotChart = { title: 'Technical Support Developer Odoo ERP Summary', subtitle: pivot ? 'Tasks Analysis · Count per proyek · Excel pivot Odoo' : 'Belum ada Excel pivot Odoo', kind: 'column', series: ['Count'], rows: pivot ? [...pivot.rows].sort((a, b) => pivotProjectRank(a.project) - pivotProjectRank(b.project) || a.project.localeCompare(b.project)).map(row => ({ label: row.project, values: [row.count] })) : [], total: pivot ? pivot.total : 0 };
  return [byDate.length ? byDate : [empty('Task by Start Date & Project', 'stack')], byStatus.length ? byStatus : [empty('Task by Start Date & Status', 'line')], pivot !== undefined ? [pivotChart] : byProject.length ? byProject : [empty('Task Summary by Project', 'column')]];
}

const escHtml = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c] || c));
const palette = i => `var(--report-series-${i % 8})`;
const wrapText = (value, width = 21) => {
  const words = value.split(/\s+/); const lines = []; let current = '';
  for (const word of words) {
    if ((current + ' ' + word).trim().length > width && current) { lines.push(current); current = ''; }
    current = (current + ' ' + word).trim();
  }
  if (current) lines.push(current);
  return lines;
};

/* Deterministic vector artwork; no AI, screenshot, external image, or private data request. */
function reportChartSvg(chart, compact = false) {
  const legendRows = Math.ceil(chart.series.length / 4);
  const width = 1120, height = compact ? 240 : chart.kind === 'column' ? 560 : chart.kind === 'bar' ? Math.max(480, 90 + chart.rows.length * 34) : 480 + Math.max(0, legendRows - 1) * 22;
  const left = chart.kind === 'bar' ? 300 : 62, right = 45, top = compact ? 25 : 42, bottom = compact ? 35 : chart.kind === 'bar' ? 50 : chart.kind === 'column' ? 60 : 126 + Math.max(0, legendRows - 1) * 22;
  const plotW = width - left - right, plotH = height - top - bottom;
  const max = Math.max(1, ...chart.rows.map(r => chart.kind === 'stack' || chart.kind === 'column' ? r.values.reduce((a, b) => a + b, 0) : Math.max(0, ...r.values)));
  const step = chart.kind === 'column' && max <= 10 ? 1 : Math.max(1, Math.ceil(max / 5)), ceiling = Math.ceil(max / step) * step;
  const font = 'font-family:Arial,sans-serif;font-size:14px;fill:var(--report-ink)';
  let body = `<rect width="${width}" height="${height}" style="fill:var(--report-paper)"/>`;
  if (!chart.rows.length) return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escHtml(chart.title)}"><rect width="100%" height="100%" style="fill:var(--report-paper)"/><text x="560" y="${height / 2}" text-anchor="middle" style="${font}">${escHtml(chart.subtitle === 'Belum ada Excel pivot Odoo' ? chart.subtitle : 'Tidak ada task belum DONE')}</text></svg>`;
  for (let value = 0; value <= ceiling; value += step) {
    const horizontal = chart.kind !== 'bar';
    const x = left + value / ceiling * plotW, y = top + plotH - value / ceiling * plotH;
    body += horizontal ? `<line x1="${left}" x2="${width - right}" y1="${y}" y2="${y}" style="stroke:var(--report-grid)" stroke-dasharray="3 3"/><text x="${left - 12}" y="${y + 5}" text-anchor="end" style="${font}">${value}</text>` : `<line x1="${x}" x2="${x}" y1="${top}" y2="${top + plotH}" style="stroke:var(--report-grid)" stroke-dasharray="3 3"/><text x="${x}" y="${top + plotH + 23}" text-anchor="middle" style="${font}">${value}</text>`;
  }
  if (chart.kind === 'bar') {
    const rowH = plotH / chart.rows.length;
    chart.rows.forEach((row, i) => {
      const value = row.values[0] || 0, y = top + i * rowH + rowH * .18;
      const lines = wrapText(row.label, 30);
      body += `<text x="${left - 15}" y="${y + rowH * .32 - (lines.length - 1) * 8}" text-anchor="end" style="${font}">${lines.map((line, j) => `<tspan x="${left - 15}" dy="${j ? 16 : 0}">${escHtml(line)}</tspan>`).join('')}</text><rect x="${left}" y="${y}" width="${value / ceiling * plotW}" height="${rowH * .62}" rx="2" style="fill:${palette(0)}"/><text x="${left + value / ceiling * plotW + 8}" y="${y + rowH * .4}" style="${font}">${value}</text>`;
    });
  } else {
    const colW = plotW / chart.rows.length, barW = chart.kind === 'column' ? colW * .72 : Math.min(50, colW * .55);
    chart.rows.forEach((row, i) => {
      const x = left + colW * (i + .5); let acc = 0;
      if (chart.kind === 'stack' || chart.kind === 'column') row.values.forEach((value, j) => {
        if (!value) return;
        const h = value / ceiling * plotH, y = top + plotH - acc - h; acc += h;
        body += `<rect x="${x - barW / 2}" y="${y}" width="${barW}" height="${h}" rx="2" style="fill:${chart.kind === 'column' ? 'var(--report-odoo-bar)' : palette(j)}"/>${chart.kind === 'column' ? '' : `<text x="${x}" y="${y + h / 2 + 5}" text-anchor="middle" style="${font};fill:var(--report-on-series)">${value}</text>`}`;
      });
      body += chart.kind === 'column' ? `<text x="${x}" y="${top + plotH + 24}" text-anchor="middle" style="${font};font-size:12px">${wrapText(row.label, Math.max(8, Math.floor(colW / 8))).map((line, j) => `<tspan x="${x}" dy="${j ? 14 : 0}">${escHtml(line)}</tspan>`).join('')}</text>` : `<text transform="translate(${x - 5},${top + plotH + 22}) rotate(-25)" text-anchor="end" style="${font};font-size:12px">${escHtml(row.label)}</text>`;
    });
    if (chart.kind === 'line') chart.series.forEach((_, j) => {
      const points = chart.rows.map((r, i) => [left + colW * (i + .5), top + plotH - (r.values[j] || 0) / ceiling * plotH]);
      body += `<polyline points="${points.map(p => p.join(',')).join(' ')}" fill="none" stroke-width="2" style="stroke:${palette(j)}"/>`;
      points.forEach((p, i) => { body += `<circle cx="${p[0]}" cy="${p[1]}" r="4" style="fill:${palette(j)}"/><text x="${p[0]}" y="${(p[1] || 0) - 10 - j * 12}" text-anchor="middle" style="${font};fill:${palette(j)}">${chart.rows[i] ? chart.rows[i].values[j] || 0 : 0}</text>`; });
    });
    chart.series.forEach((name, i) => {
      const x = chart.kind === 'column' ? width - right - 70 : 65 + (i % 4) * 270, y = chart.kind === 'column' ? top - 12 : height - 21 - (legendRows - 1 - Math.floor(i / 4)) * 22;
      body += `<rect x="${x}" y="${y - 11}" width="11" height="11" style="fill:${chart.kind === 'column' ? 'var(--report-odoo-bar)' : palette(i)}"/><text x="${x + 18}" y="${y}" style="${font};font-size:11px">${escHtml(name.length > 38 ? name.slice(0, 36) + '…' : name)}</text>`;
    });
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escHtml(chart.title)}">${body}</svg>`;
}

/* ---------- Penyimpanan data tim ---------- */
async function loadDataset() {
  const { data, error } = await sb.from('pmo_datasets').select('filename, tasks, pivot, screenshots, uploaded_by_email, updated_at').eq('id', DATASET_ID).maybeSingle();
  if (error) throw error;
  if (!data) return undefined;
  return { filename: data.filename, tasks: data.tasks || [], pivot: data.pivot || null, screenshots: normalizeScreenshots(data.screenshots), uploadedByEmail: data.uploaded_by_email, updatedAt: data.updated_at };
}
async function upsertDataset(fields) {
  const { error } = await sb.from('pmo_datasets').upsert({ id: DATASET_ID, uploaded_by: null, uploaded_by_email: 'Pengguna dashboard', updated_at: new Date().toISOString(), ...fields });
  if (error) throw error;
}
async function listArchives() {
  const {data,error}=await sb.from('pmo_weekly_archives').select('id,filename,uploaded_at').order('uploaded_at',{ascending:false});
  if(error) throw error;
  const selected=state.archiveId;
  $('archive-select').innerHTML='<option value="">Data terbaru</option>'+data.map(a=>`<option value="${escHtml(a.id)}">${escHtml(new Date(a.uploaded_at).toLocaleDateString('id-ID'))} · ${escHtml(a.filename)}</option>`).join('');
  $('archive-select').value=selected;
}
async function selectArchive(id) {
  if(!id){state.archiveId='';await load();return;}
  try {
    const {data,error}=await sb.from('pmo_weekly_archives').select('id,filename,tasks,pivot,screenshots,uploaded_at,updated_at').eq('id',id).single();
    if(error) throw error;
    const screenshots=await Promise.all(normalizeScreenshots(data.screenshots).map(image=>image?window.pmoExport.fitReportImage(image):null));
    state.archiveId=id;state.tasks=data.tasks||[];state.filename=data.filename;state.pivot=data.pivot||null;state.screenshots=screenshots;state.owner='';
    state.filters={Project:[],Status:[],Type:[],PIC:[]};state.search='';$('task-search').value='';state.page=1;state.sort=null;
    showError('');renderAll();
  } catch { $('archive-select').value=state.archiveId;showError('Arsip tidak dapat dimuat. Periksa koneksi internet.'); }
}
const saveUploadedTasks = (filename, tasks) => upsertDataset({ filename, tasks });
const clearUploadedTasks = () => upsertDataset({ filename: 'Data kosong', tasks: [] });
const savePivot = pivot => upsertDataset({ pivot });
const saveScreenshots = screenshots => upsertDataset({ screenshots });

/* ---------- Laporan PDF ---------- */
const esc = v => String(v == null ? '-' : v).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c] || c));
const metaRow = (label, value) => `<tr><td>${esc(label)}</td><td>${esc(value || '-')}</td></tr>`;

function openWeeklyReport(tasks, reportDate = new Date(), filename = 'Excel mingguan', pivot = null, screenshots = [null, null]) {
  const images = normalizeScreenshots(screenshots);
  if (!images[0] || !images[1]) throw new Error('Unggah screenshot gambar 1 dan 2 terlebih dahulu.');
  if (!pivot) throw new Error('Unggah Excel pivot Odoo untuk diagram 3 terlebih dahulu.');
  const tab = window.open('', '_blank');
  if (!tab) throw new Error('Browser memblokir tab laporan. Izinkan pop-up, lalu coba lagi.');
  const date = reportDate.toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
  const header = `<header><h1>Weekly Update ${esc(date)}</h1><p>IT Corporate Application</p></header>`;
  const projects = reportProjects(tasks);
  let previousSection = '';
  const projectPages = projects.map(project => {
    const list = openReportTasks(tasks).filter(t => t.Project === project);
    const pics = [...new Set(list.map(t => t.PIC).filter(p => p !== '-'))].join(', ') || '-';
    const key = Object.keys(PROJECT_META).find(k => k.toLowerCase() === project.toLowerCase()) || Object.keys(PROJECT_META).find(k => k.toLowerCase().includes(project.toLowerCase()) || project.toLowerCase().includes(k.toLowerCase()));
    const meta = key ? PROJECT_META[key] || {} : {};
    const section = meta.section && meta.section !== previousSection ? `<h2>${esc(meta.section).replace(/\n/g, '<br>')}</h2>` : '';
    if (meta.section) previousSection = meta.section;
    return `<section class="page">${header}${section}<table class="meta"><tbody>${metaRow('Project Name', project)}${metaRow('PM', meta.pm)}${metaRow('SA', meta.sa)}${metaRow('Developer', meta.dev)}${metaRow('User (PIC)', meta.user || pics)}${metaRow('URL Web — Staging', meta.staging)}${metaRow('URL Web — Production', meta.prod)}${metaRow('Target Live', meta.targetLive)}${metaRow('Project Priority', meta.priority)}${metaRow('Project Stage', meta.stage)}</tbody></table><table><thead><tr><th>No</th><th>Task Name</th><th>Task Status</th><th>Task Type</th><th>PIC</th><th>Due Date</th><th>Actual Date</th><th>Note</th></tr></thead><tbody>${list.map((t, i) => `<tr><td>${i + 1}</td><td>${esc(t['Task Name'])}</td><td>${esc(t.Status)}</td><td>${esc(t.Type)}</td><td>${esc(t.PIC)}</td><td>${esc(t['Due Date'])}</td><td>${esc(t['Actual Date'] || t.From)}</td><td></td></tr>`).join('')}</tbody></table></section>`;
  }).join('');
  const chartPages = images.map((image, index) => `<section class="page chart-page">${header}<h2>${index + 1}. ${esc(SHOT_TITLES[index])}</h2><div class="image-wrap"><img src="${esc(image)}" alt="${esc(SHOT_TITLES[index])}"></div><p class="source">Source: https://helpdesk.mncgroup.com/ · Screenshot yang diunggah</p></section>`).join('') + buildReportCharts(tasks, true, pivot).slice(2).map(family => family.map(chart => `<section class="page chart-page">${header}<h2>3. ${esc(chart.title)}</h2><p>${esc(chart.subtitle)}</p><p>Total records: ${chart.total} · Generated: ${esc(date)}</p><div class="report-chart">${reportChartSvg(chart)}</div><p class="source">Source: ${esc(pivot.filename)} · Count dari pivot Tasks Analysis; status dan tanggal tidak tersedia di pivot</p></section>`).join('')).join('');
  const releasePage = `<section class="page">${header}<h3>Release Period 1 Jan – 31 July 2026:</h3><table><thead><tr><th>No</th><th>Website / Web Apps</th><th>Details</th></tr></thead><tbody><tr><td>1</td><td>OMS Contents</td><td>Order management system</td></tr><tr><td>2</td><td>MNC ASIA HOLDING</td><td>Company Profile</td></tr><tr><td>3</td><td>IMS</td><td>Inventory management system</td></tr><tr><td>4</td><td>RnD</td><td>Dashboard</td></tr></tbody></table><h3>Ready to Release Period 1 Jan – 30 July 2026:</h3><table><thead><tr><th>No</th><th>Website / Web Apps</th><th>Details</th></tr></thead><tbody><tr><td>1</td><td>Talent Casting Revamp</td><td></td></tr></tbody></table></section>`;
  const wikiPages = Array.from({ length: Math.ceil(WIKI.length / 12) }, (_, page) => `<section class="page">${header}${page === 0 ? '<h2>Wiki</h2>' : ''}<table><thead><tr><th>No</th><th>Project Name</th><th>URL STAGING</th><th>URL PROD</th><th>Project Info</th></tr></thead><tbody>${WIKI.slice(page * 12, (page + 1) * 12).map(w => `<tr><td>${esc(w.no)}</td><td>${esc(w.proj)}</td><td>${esc(w.staging)}</td><td>${esc(w.prod)}</td><td>${esc(w.info)}</td></tr>`).join('')}</tbody></table></section>`).join('');
  tab.document.write(`<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Weekly Update ${esc(date)}</title><style>:root{--report-paper:#fff;--report-ink:#172126;--report-muted:#57636c;--report-grid:#dbe1e5;--report-surround:#525659;--report-toolbar:#172126;--report-on-series:#fff;--report-series-0:#287bbc;--report-series-1:#cf554d;--report-series-2:#18856a;--report-series-3:#9a7526;--report-series-4:#7756a1;--report-series-5:#377a83;--report-series-6:#ba5679;--report-series-7:#59636d;--report-shadow:0 2px 14px #2226}
    *{box-sizing:border-box}body{margin:0;background:var(--report-surround);color:var(--report-ink);font:13px Arial,sans-serif}.toolbar{position:sticky;top:0;background:var(--report-toolbar);color:var(--report-paper);padding:12px 24px;display:flex;align-items:center;justify-content:space-between;z-index:5}.toolbar button{background:var(--report-series-0);color:var(--report-paper);border:0;border-radius:5px;padding:9px 18px;cursor:pointer;font-weight:700}.page{background:var(--report-paper);width:297mm;min-height:210mm;margin:18px auto;padding:15mm 18mm;box-shadow:var(--report-shadow);break-after:page;overflow-wrap:anywhere}header{margin-bottom:24px}h1{font-size:24px;margin:0 0 3px}header p{margin:0;color:var(--report-muted)}h2{font-size:19px;margin:18px 0 12px}h3{font-size:16px;margin:18px 0}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid var(--report-ink);padding:6px;text-align:left;vertical-align:top}th{font-weight:700}.meta{width:60%;margin-bottom:20px}.meta td:first-child{width:150px}.image-wrap{text-align:center;height:450px;display:flex;align-items:center;justify-content:center}.image-wrap img{max-width:85%;max-height:100%;object-fit:contain}.source{text-align:center;font-size:12px}.source a{color:var(--report-series-0)}@media print{.toolbar{display:none}.page{width:100%;margin:0;box-shadow:none;break-after:page}@page{size:A4 landscape;margin:0}}@media(max-width:1100px){.page{transform-origin:top left;max-width:100%;min-height:initial;overflow:auto}}
    :root{--report-odoo-bar:#4ba3ed}.report-chart svg{width:100%;height:auto;max-height:140mm}.chart-page .report-chart{margin-top:12px}.chart-page header{margin-bottom:12px}.chart-page h2{margin:10px 0;text-align:center}.chart-page p{margin:6px 0;text-align:center}.image-wrap img{max-width:100%}.page{print-color-adjust:exact;-webkit-print-color-adjust:exact}table tr{break-inside:avoid}.page:last-child{break-after:auto}
  </style></head><body><div class="toolbar"><strong>Weekly Update ${esc(date)} — IT Corporate Application</strong><button onclick="window.print()">Print / Save as PDF</button></div>${projectPages}${chartPages}${releasePage}${wikiPages}</body></html>`);
  tab.document.close();
}

/* ============================================================
   Aplikasi (tampilan & interaksi)
   ============================================================ */
const COLUMNS = ['Project','Task Name','Status','Type','PIC','From','Due Date','Overdue Date'];
const PALETTE = ['#34d399', '#fbbf24', '#22d3ee', '#a78bfa', '#8b5cf6', '#fb7185'];
const formatNumber = n => new Intl.NumberFormat('id-ID').format(n);
const uniqueSorted = values => [...new Set(values.filter(x => x && x !== '-'))].sort((a, b) => a.localeCompare(b, 'id'));

const state = {
  archiveId: '', tasks: [], filename: '', pivot: null, screenshots: [null, null], owner: '',
  search: '', filters: { Project: [], Status: [], Type: [], PIC: [] },
  sort: null, ascending: true, page: 1,
};
const charts = {};
const $ = id => document.getElementById(id);

function showError(message) {
  const box = $('error-box');
  if (message) { box.textContent = message; box.hidden = false; }
  else { box.hidden = true; }
}

function filteredTasks() {
  const query = state.search.trim().toLocaleLowerCase();
  return state.tasks.filter(t =>
    (!query || [t.Project, t['Task Name'], t.PIC].some(x => x.toLocaleLowerCase().includes(query))) &&
    ['Project', 'Status', 'Type', 'PIC'].every(key => !state.filters[key].length || state.filters[key].includes(t[key]))
  );
}
function orderedTasks() {
  const list = filteredTasks();
  const sort = state.sort;
  const sorted = sort ? [...list].sort((a, b) => {
    const left = sort === 'Overdue Date' ? overdueDays(a) : (sort === 'Due Date' || sort === 'From') ? (parseDate(a[sort])?.getTime() || 0) : a[sort];
    const right = sort === 'Overdue Date' ? overdueDays(b) : (sort === 'Due Date' || sort === 'From') ? (parseDate(b[sort])?.getTime() || 0) : b[sort];
    return (typeof left === 'number' && typeof right === 'number' ? left - right : String(left).localeCompare(String(right), 'id')) * (state.ascending ? 1 : -1);
  }) : list;
  return window.pmoExport.groupProjectTasks(sorted);
}

/* ---------- KPI ---------- */
function renderKpis(filtered) {
  const projects = uniqueSorted(filtered.map(t => t.Project));
  const done = filtered.filter(t => t.Status === 'DONE').length;
  const active = filtered.filter(t => t.Status === 'IN PROGRESS' || t.Status === 'TODO').length;
  const completion = filtered.length ? Math.round(done / filtered.length * 100) : 0;
  $('kpi-projects-value').textContent = formatNumber(projects.length);
  $('kpi-tasks-value').textContent = formatNumber(filtered.length);
  $('kpi-completion-value').textContent = completion + '%';
  $('kpi-completion-bar').style.width = completion + '%';
  $('kpi-active-value').textContent = formatNumber(active);
  $('project-popover-title').textContent = `Daftar Proyek (${projects.length})`;
  $('project-popover-list').innerHTML = projects.map(p => `<button type="button" class="btn btn-secondary btn-sm" data-project="${escHtml(p)}">${escHtml(p)}</button>`).join('');
  $('project-popover-list').querySelectorAll('button').forEach(btn => btn.addEventListener('click', () => {
    state.filters = { Project: [btn.dataset.project], Status: [], Type: [], PIC: [] };
    state.page = 1; $('project-popover').hidden = true; renderAll();
  }));
}

/* ---------- Filter ---------- */
function renderFilters() {
  const options = {
    Project: uniqueSorted(state.tasks.map(t => t.Project)),
    Status: uniqueSorted([...STATUSES, ...state.tasks.map(t => t.Status)]),
    Type: uniqueSorted(state.tasks.map(t => t.Type)),
    PIC: uniqueSorted(state.tasks.map(t => t.PIC)),
  };
  document.querySelectorAll('.filter-field[data-filter]').forEach(field => {
    const key = field.dataset.filter;
    const selected = state.filters[key];
    const trigger = field.querySelector('.multi-trigger span');
    trigger.textContent = selected.length ? selected.join(', ') : `Semua ${key}...`;
    trigger.classList.toggle('has-value', selected.length > 0);
    const menu = field.querySelector('.multi-menu');
    menu.innerHTML = options[key].length ? options[key].map(option => `
      <button type="button" class="multi-option" data-value="${escHtml(option)}">
        <span class="check">${selected.includes(option) ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>' : ''}</span>${escHtml(option)}
      </button>`).join('') : '<p class="muted" style="padding:8px">Belum ada pilihan</p>';
    menu.querySelectorAll('.multi-option').forEach(btn => btn.addEventListener('click', () => {
      const value = btn.dataset.value;
      state.filters[key] = state.filters[key].includes(value) ? state.filters[key].filter(x => x !== value) : [...state.filters[key], value];
      state.page = 1; renderAll();
    }));
  });
  const tags = Object.keys(state.filters).flatMap(key => state.filters[key].map(value => ({ key, value })));
  const tagBox = $('filter-tags');
  tagBox.hidden = !tags.length;
  tagBox.innerHTML = tags.map(tag => `<button type="button" class="filter-tag" data-key="${tag.key}" data-value="${escHtml(tag.value)}">${escHtml(tag.value)} ✕</button>`).join('');
  tagBox.querySelectorAll('.filter-tag').forEach(btn => btn.addEventListener('click', () => {
    state.filters[btn.dataset.key] = state.filters[btn.dataset.key].filter(x => x !== btn.dataset.value);
    state.page = 1; renderAll();
  }));
}

/* ---------- Grafik (Chart.js) ---------- */
Chart.defaults.color = '#a8b3c7';
Chart.defaults.borderColor = 'rgba(120,130,150,0.22)';
Chart.defaults.font.family = 'Inter, system-ui, sans-serif';
Chart.defaults.font.size = 11;
const tooltipStyle = { backgroundColor: '#232a3d', borderColor: 'rgba(120,130,150,0.4)', borderWidth: 1, titleColor: '#f2f5fb', bodyColor: '#c9d2e4', padding: 10, cornerRadius: 6 };

function makeChart(id, config) {
  if (charts[id]) charts[id].destroy();
  charts[id] = new Chart($(id), config);
}
function pickFilter(key, value) {
  state.filters = { Project: [], Status: [], Type: [], PIC: [] };
  state.filters[key] = [value];
  state.search = ''; $('task-search').value = ''; state.page = 1;
  renderAll();
  setTimeout(() => $('task-table').scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
}
function renderCharts(filtered) {
  const statusData = STATUSES.map(name => ({ name, value: filtered.filter(t => t.Status === name).length })).filter(x => x.value);
  makeChart('chart-status', statusData.length ? {
    type: 'doughnut',
    data: { labels: statusData.map(x => x.name), datasets: [{ data: statusData.map(x => x.value), backgroundColor: PALETTE, borderColor: '#232a3d', borderWidth: 3 }] },
    options: { maintainAspectRatio: false, cutout: '65%', plugins: { legend: { position: 'bottom', labels: { usePointStyle: true, pointStyle: 'circle', boxWidth: 8 } }, tooltip: tooltipStyle }, onClick: (e, el) => { if (el.length) pickFilter('Status', statusData[el[0].index].name); } },
  } : emptyChartConfig());

  const picNames = uniqueSorted(filtered.map(t => t.PIC)).map(name => ({ name, total: filtered.filter(t => t.PIC === name).length })).sort((a, b) => b.total - a.total).slice(0, 7).map(x => x.name);
  makeChart('chart-pic', picNames.length ? {
    type: 'bar',
    data: { labels: picNames, datasets: STATUSES.map((status, i) => ({ label: status, data: picNames.map(name => filtered.filter(t => t.PIC === name && t.Status === status).length), backgroundColor: PALETTE[i], stack: 'a' })) },
    options: { maintainAspectRatio: false, scales: { x: { stacked: true, grid: { display: false } }, y: { stacked: true, ticks: { precision: 0 } } }, plugins: { legend: { display: false }, tooltip: tooltipStyle }, onClick: (e, el) => { if (el.length) pickFilter('PIC', picNames[el[0].index]); } },
  } : emptyChartConfig());

  const typeData = uniqueSorted(filtered.map(t => t.Type)).map(name => ({ name, value: filtered.filter(t => t.Type === name).length })).sort((a, b) => b.value - a.value);
  makeChart('chart-type', typeData.length ? {
    type: 'doughnut',
    data: { labels: typeData.map(x => x.name), datasets: [{ data: typeData.map(x => x.value), backgroundColor: typeData.map((_, i) => PALETTE[i % PALETTE.length]), borderColor: '#232a3d', borderWidth: 3 }] },
    options: { maintainAspectRatio: false, cutout: '65%', plugins: { legend: { position: 'bottom', labels: { usePointStyle: true, pointStyle: 'circle', boxWidth: 8 } }, tooltip: tooltipStyle }, onClick: (e, el) => { if (el.length) pickFilter('Type', typeData[el[0].index].name); } },
  } : emptyChartConfig());

  const projectData = uniqueSorted(filtered.map(t => t.Project)).map(name => ({ name, value: filtered.filter(t => t.Project === name).length })).sort((a, b) => b.value - a.value).slice(0, 8);
  makeChart('chart-project', projectData.length ? {
    type: 'bar',
    data: { labels: projectData.map(x => x.name), datasets: [{ data: projectData.map(x => x.value), backgroundColor: '#8b5cf6', borderRadius: 3 }] },
    options: { indexAxis: 'y', maintainAspectRatio: false, scales: { x: { ticks: { precision: 0 } }, y: { grid: { display: false } } }, plugins: { legend: { display: false }, tooltip: tooltipStyle }, onClick: (e, el) => { if (el.length) pickFilter('Project', projectData[el[0].index].name); } },
  } : emptyChartConfig());
}
function emptyChartConfig() {
  return { type: 'doughnut', data: { labels: ['Tidak ada data'], datasets: [{ data: [1], backgroundColor: ['rgba(120,130,150,0.25)'], borderWidth: 0 }] }, options: { maintainAspectRatio: false, cutout: '65%', plugins: { legend: { display: false }, tooltip: { enabled: false } }, events: [] } };
}

/* ---------- Screenshot Helpdesk ---------- */
function renderScreenshots() {
  $('shot-grid').innerHTML = state.screenshots.map((image, index) => `
    <article class="generated-diagram">
      <header class="generated-diagram-head"><div><span class="diagram-number">0${index + 1}</span><h3>${SHOT_TITLES[index]}</h3><p>https://helpdesk.mncgroup.com/</p></div></header>
      <div class="shot-drop" tabindex="0" aria-label="Screenshot ${index + 1}" data-index="${index}">
        ${image ? `<img src="${image}" alt="${SHOT_TITLES[index]}">` : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg>'}
      </div>
      <div class="shot-actions">
        <input type="file" hidden accept="image/png,image/jpeg,image/webp" aria-label="File screenshot ${index + 1}" data-index="${index}">
        <button class="btn btn-secondary btn-sm" type="button" data-upload="${index}">Unggah Screenshot ${index + 1}</button>
        ${image ? `<button class="btn btn-ghost btn-icon" type="button" aria-label="Hapus screenshot ${index + 1}" title="Hapus screenshot ${index + 1}" data-remove="${index}">✕</button>` : ''}
      </div>
    </article>`).join('');
  $('shot-grid').querySelectorAll('[data-upload]').forEach(btn => btn.addEventListener('click', () => {
    $('shot-grid').querySelector(`input[data-index="${btn.dataset.upload}"]`).click();
  }));
  $('shot-grid').querySelectorAll('input[type=file]').forEach(input => input.addEventListener('change', () => {
    if (input.files[0]) changeScreenshot(Number(input.dataset.index), input.files[0]);
    input.value = '';
  }));
  $('shot-grid').querySelectorAll('[data-remove]').forEach(btn => btn.addEventListener('click', () => changeScreenshot(Number(btn.dataset.remove), null)));
  $('shot-grid').querySelectorAll('.shot-drop').forEach(drop => {
    const index = Number(drop.dataset.index);
    drop.addEventListener('dragover', e => e.preventDefault());
    drop.addEventListener('drop', e => { e.preventDefault(); const file = e.dataTransfer.files[0]; if (file) changeScreenshot(index, file); });
    drop.addEventListener('paste', e => {
      const item = Array.from(e.clipboardData.items).find(x => x.type.startsWith('image/'));
      const file = item && item.getAsFile();
      if (file) { e.preventDefault(); changeScreenshot(index, file); }
    });
  });
}
async function changeScreenshot(index, file) {
  if(state.archiveId)return;
  try {
    const value = file ? await window.pmoExport.fitReportImage(await readScreenshot(file)) : null;
    const next = [index === 0 ? value : state.screenshots[0], index === 1 ? value : state.screenshots[1]];
    await saveScreenshots(next);
    state.screenshots = next; showError(''); renderScreenshots();
  } catch (e) { showError(e instanceof Error ? e.message : 'Screenshot gagal disimpan.'); }
}

/* ---------- Pivot Odoo & diagram ---------- */
function renderPivot() {
  $('pivot-info').textContent = state.pivot ? `${state.pivot.filename} · ${state.pivot.total} task · ${state.pivot.rows.length} proyek` : 'Belum ada Excel pivot Odoo';
  const families = buildReportCharts(state.tasks, true, state.pivot);
  $('odoo-diagrams').innerHTML = families.slice(2).map(charts => charts.map(chart => `
    <article class="generated-diagram">
      <header class="generated-diagram-head"><div><span class="diagram-number">03</span><h3>${escHtml(chart.title)}</h3><p>${escHtml(chart.subtitle)}</p></div><span class="data-badge">${chart.total} task</span></header>
      <div class="diagram-art">${reportChartSvg(chart)}</div>
    </article>`).join('')).join('');
}
async function handlePivot(file) {
  if(state.archiveId)return;
  if (!file) return;
  const btn = $('btn-pivot');
  btn.disabled = true; btn.textContent = 'Menyimpan...';
  try {
    const data = await readPivot(file);
    await savePivot(data);
    state.pivot = data; showError(''); renderPivot();
  } catch (e) { showError(e instanceof Error ? e.message : 'Pivot gagal dibaca.'); }
  finally { btn.disabled = false; btn.textContent = 'Unggah Pivot Odoo'; }
}

/* ---------- Tabel ---------- */
function renderTable(ordered) {
  $('table-head').innerHTML = COLUMNS.map(column => `<th><button type="button" data-sort="${column}">${column === 'PIC' ? 'PIC / Resource' : column} ⇅</button></th>`).join('');
  $('table-head').querySelectorAll('button').forEach(btn => btn.addEventListener('click', () => {
    const column = btn.dataset.sort;
    state.ascending = state.sort === column ? !state.ascending : true;
    state.sort = column; renderAll();
  }));
  const pages = Math.max(1, Math.ceil(ordered.length / 12));
  const page = Math.min(state.page, pages);
  const visible = ordered.slice((page - 1) * 12, page * 12);
  const spans = window.pmoExport.projectRowSpans(visible.map(t => t.Project));
  $('table-body').innerHTML = visible.length ? visible.map((t, i) => `<tr>${spans[i] ? `<td class="project-cell" rowspan="${spans[i]}">${escHtml(t.Project)}</td>` : ''}<td class="task-name-cell">${escHtml(t['Task Name'])}</td><td><span class="status-pill status-${t.Status.replace(/\s/g, '')}">${escHtml(t.Status)}</span></td><td>${escHtml(t.Type)}</td><td>${escHtml(t.PIC)}</td><td>${escHtml(t.From)}</td><td>${escHtml(t['Due Date'])}</td><td>${overdueDays(t) > 0 ? `<span class="overdue">${overdueDays(t)} hari terlambat</span>` : '-'}</td></tr>`).join('') : '<tr><td colspan="8" style="text-align:center">Tidak ada task yang sesuai.</td></tr>';
  $('row-count').textContent = `Showing ${formatNumber(ordered.length)} rows`;
  $('page-info').textContent = `Halaman ${page} dari ${pages}`;
  $('page-current').textContent = page;
  $('btn-prev').disabled = page <= 1;
  $('btn-next').disabled = page >= pages;
  $('btn-pdf').disabled = !ordered.length && !state.pivot;
  $('btn-ppt').disabled = !ordered.length;
  $('btn-xlsx').disabled = !ordered.length;
  $('btn-csv').disabled = !ordered.length;
}

/* ---------- Render utama ---------- */
function renderAll() {
  const filtered = filteredTasks();
  const ordered = orderedTasks();
  $('data-badge').textContent = `Data: ${state.filename || 'Belum ada file'}`;
  $('data-badge').title = state.filename || 'Belum ada file';
  $('owner-badge').textContent = state.owner ? `Diperbarui: ${state.owner}` : '';
  $('owner-badge').title = state.owner;
  pptReady = null;
  $('btn-ppt').textContent = 'Export PPT';
  renderKpis(filtered);
  renderFilters();
  renderCharts(filtered);
  renderScreenshots();
  renderPivot();
  renderTable(ordered);
  const archived=Boolean(state.archiveId);
  $('archive-status').textContent=archived?'Arsip · hanya baca':'Data terbaru';
  $('btn-clear').disabled=archived;$('btn-pivot').disabled=archived;
  $('upload-area').setAttribute('aria-disabled',String(archived));
  $('upload-area').tabIndex=archived?-1:0;
  $('shot-grid').querySelectorAll('button,input').forEach(el=>el.disabled=archived);

}

/* ---------- Muat data tim ---------- */
async function load() {
  await listArchives().catch(()=>showError('Daftar arsip tidak dapat dimuat.'));
  if(state.archiveId)return;
  try {
    const saved = await loadDataset();
    if (saved && Array.isArray(saved.tasks)) {
      state.tasks = saved.tasks;
      state.pivot = saved.pivot || null;
      state.screenshots = await Promise.all((saved.screenshots || [null, null]).map(image => image ? window.pmoExport.fitReportImage(image) : null));
      state.filename = saved.filename || 'Data tersimpan';
      state.owner = saved.uploadedByEmail ? `${saved.uploadedByEmail} · ${new Date(saved.updatedAt).toLocaleString('id-ID')}` : '';
    }
    showError('');
  } catch { showError('Data tim tidak dapat dimuat. Periksa koneksi internet.'); }
  renderAll();
}

/* ---------- Aksi unggah & hapus ---------- */
async function handleFile(file) {
  if(state.archiveId)return;
  if (!file) return;
  if (!/\.(xlsx|xls|csv)$/i.test(file.name)) { showError('Gunakan file .xlsx, .xls, atau .csv.'); return; }
  try {
    const data = await readTasks(file);
    const label = `${file.name} (${data.length} baris)`;
    await saveUploadedTasks(label, data);
    state.tasks = data; state.filename = label; state.sort = null;
    state.filters = { Project: [], Status: [], Type: [], PIC: [] };
    state.search = ''; $('task-search').value = ''; state.page = 1;
    showError(''); renderAll();
  } catch (e) { showError(e instanceof Error ? e.message : 'File tidak bisa dibaca.'); }
}
async function clearData() {
  if(state.archiveId)return;
  if (!window.confirm('Hapus semua data Excel tim? Semua anggota akan melihat data kosong.')) return;
  try {
    await clearUploadedTasks();
    state.tasks = []; state.filename = 'Data kosong'; state.page = 1;
    state.filters = { Project: [], Status: [], Type: [], PIC: [] };
    state.search = ''; $('task-search').value = '';
    showError(''); renderAll();
  } catch { showError('Data tersimpan gagal dihapus. Coba lagi.'); }
}
function exportPdf() {
  try { openWeeklyReport(orderedTasks(), new Date(), state.filename, state.pivot, state.screenshots); showError(''); }
  catch (e) { showError(e instanceof Error ? e.message : 'Laporan tidak bisa dibuka.'); }
}

/* ---------- Pasang semua interaksi ---------- */
function bindEvents() {
  $('archive-select').addEventListener('change',e=>selectArchive(e.target.value));
  const upload = $('upload-area'), fileInput = $('file-input');
  upload.addEventListener('click', () => fileInput.click());
  upload.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); fileInput.click(); } });
  upload.addEventListener('dragover', e => { e.preventDefault(); upload.classList.add('dragging'); });
  upload.addEventListener('dragleave', () => upload.classList.remove('dragging'));
  upload.addEventListener('drop', e => { e.preventDefault(); upload.classList.remove('dragging'); handleFile(e.dataTransfer.files[0]); });
  fileInput.addEventListener('change', () => { handleFile(fileInput.files[0]); fileInput.value = ''; });

  $('btn-clear').addEventListener('click', clearData);
  $('btn-reset').addEventListener('click', () => {
    state.filters = { Project: [], Status: [], Type: [], PIC: [] };
    state.search = ''; $('task-search').value = ''; state.page = 1; renderAll();
  });
  $('task-search').addEventListener('input', e => { state.search = e.target.value; state.page = 1; renderAll(); });

  document.querySelectorAll('.multi-trigger').forEach(trigger => trigger.addEventListener('click', () => {
    const menu = trigger.parentElement.querySelector('.multi-menu');
    const open = menu.hidden;
    document.querySelectorAll('.multi-menu').forEach(m => { m.hidden = true; });
    document.querySelectorAll('.multi-trigger').forEach(t => t.setAttribute('aria-expanded', 'false'));
    menu.hidden = !open;
    trigger.setAttribute('aria-expanded', String(open));
  }));
  document.addEventListener('mousedown', e => {
    if (!e.target.closest('.multi')) {
      document.querySelectorAll('.multi-menu').forEach(m => { m.hidden = true; });
      document.querySelectorAll('.multi-trigger').forEach(t => t.setAttribute('aria-expanded', 'false'));
    }
  });

  const kpiProjects = $('kpi-projects'), popover = $('project-popover');
  kpiProjects.addEventListener('mouseenter', () => { if (filteredTasks().length) popover.hidden = false; });
  kpiProjects.addEventListener('mouseleave', () => { popover.hidden = true; });

  $('btn-pivot').addEventListener('click', () => $('pivot-input').click());
  $('pivot-input').addEventListener('change', () => { handlePivot($('pivot-input').files[0]); $('pivot-input').value = ''; });

  $('btn-pdf').addEventListener('click', exportPdf);
  $('btn-ppt').addEventListener('click', exportPpt);
  $('btn-xlsx').addEventListener('click', () => exportFile(orderedTasks(), 'xlsx'));
  $('btn-csv').addEventListener('click', () => exportFile(orderedTasks(), 'csv'));
  $('btn-prev').addEventListener('click', () => { state.page -= 1; renderAll(); });
  $('btn-next').addEventListener('click', () => { state.page += 1; renderAll(); });
}


let pptReady = null;
async function exportPpt() {
 const btn = $('btn-ppt');
 if (pptReady) {
  const url = URL.createObjectURL(pptReady.blob);
  const link = Object.assign(document.createElement('a'), {href:url, download:pptReady.filename});
  document.body.append(link); link.click(); link.remove(); setTimeout(()=>URL.revokeObjectURL(url),40000); return;
 }
 btn.disabled=true; btn.textContent='Membuat PPT...';
 try { pptReady=await window.pmoExport.generateWeeklyPpt(orderedTasks(),state.screenshots); btn.textContent='Unduh PPT'; showError(''); }
 catch(e){btn.textContent='Export PPT';showError(e instanceof Error?e.message:'PPT gagal dibuat.');}
 finally {btn.disabled=false;}
}

/* ---------- Mulai ---------- */
bindEvents();
load();
sb.channel('pmo-dataset').on('postgres_changes', { event: '*', schema: 'public', table: 'pmo_datasets' }, () => { load(); }).subscribe();
